      es: ["Inaugurado en el año 2016", "Consta de 4 edificios principales", "Superficie total: 30.000 m²", "Capacidad de la ópera: 1.200 asientos", "Altura de la cúpula principal: 45 m", "108 elementos de hormigón en la fachada"],
      pt: ["Inaugurado em 2016", "Compreende 4 edifícios principais", "Área total: 30.000 m²", "Capacidade da casa de ópera: 1.200 lugares", "Altura da cúpula principal: 45 m", "108 elementos de betão na fachada"],
      fr: ["Ouvert en 2016", "Comprend 4 bâtiments principaux", "Superficie totale : 30 000 m²", "Capacité de l'opéra : 1 200 places", "Hauteur de la coupole principale : 45 m", "108 éléments en béton sur la façade"],
