      en: ["The ASCC complex was officially inaugurated on February 5, 2018.", "It covers a vast site area of approximately 130,000 square meters.", "The center features 22 galleries with over 800 individual exhibits.", "It is recognized as the largest cultural project of its kind in the world.", "The Natural History Museum contains a massive prehistoric dinosaur gallery.", "The project was honored with the 'Leading Culture Destination' award in 2021."],
      es: ["Inaugurado en 2017", "Superficie total: 137.000 m²", "4 museos bajo un mismo techo", "Costes de construcción: 800 millones de KWD", "Capacidad de visitantes: 10.000 por día", "Alberga más de 1.000 exhibiciones interactivas"],
