      fr: ["Ouvert en 2017", "Superficie totale : 137 000 m²", "4 musées sous un même toit", "Coûts de construction : 800 millions de KWD", "Capacité d'accueil : 10 000 visiteurs par jour", "Abrite plus de 1 000 objets exposés interactifs"],
