      ro: ["Prima fază a parcului a fost finalizată și deschisă în martie 2015.", "Suprafața totală a parcului este de aproximativ 200.000 mp.", "Amplasamentul coincide cu traseul celei de-a treia centuri de apărare a orașului.", "Muzeul Habitat oferă informații detaliate despre flora și fauna din Kuweit.", "Monumentul Martirilor este o structură simbolică centrală în cadrul parcului.", "Designul peisagistic include grădini tematice și piste de jogging moderne."],
