      es: ["Inaugurado en 2015", "Superficie: 86 hectáreas", "Consta de 3 secciones principales", "Museo con 2.000 m² de superficie de exposición", "Parques con más de 30.000 árboles", "Anfiteatro con 2.000 asientos"],
