    facts: {
      de: ["Liegt direkt am Wasser in Fahaheel", "Die Springbrunnen zeigen choreografierte Shows", "Verbindet modernen Einzelhandel mit traditionellen Souq-Elementen", "Umfasst einen Jachthafen"],
      hu: ["Közvetlenül a vízparton található Fahaheel-ben", "A szökőkutak koreografált műsorokat mutatnak be", "A modern kiskereskedelmet hagyományos souq-elemekkel ötvözi", "Egy jachtkikötőt is magában foglal"],
      ro: ["Situat chiar pe malul apei în Fahaheel", "Fântânile prezintă spectacole coregrafiate", "Combină retailul modern cu elemente tradiționale de souq", "Include un port de agrement"],
      en: ["Located right on the waterfront in Fahaheel", "The fountains feature choreographed shows", "Combines modern retail with traditional souq elements", "Includes a marina"],
      es: ["Situado junto al agua en Fahaheel", "Las fuentes presentan espectáculos coreografiados", "Combina el comercio moderno con elementos de un zoco tradicional", "Incluye un puerto deportivo"],
      pt: ["Situado à beira-mar em Fahaheel", "As fontes apresentam espetáculos coreografados", "Combina o retalho moderno com elementos tradicionais de souq", "Inclui uma marina"],
      fr: ["Situé directement au bord de l'eau à Fahaheel", "Les fontaines proposent des spectacles chorégraphiés", "Allie commerce moderne et éléments de souk traditionnel", "Comprend un port de plaisance"],
    },
    descriptionAdvanced: {
      de: "Die Al Kout Mall in Fahaheel ist das Herzstück des Al Kout Projekts, Kuwaits größtem Lifestyle-Ziel am Wasser. Der Komplex verbindet modernen Einzelhandel mit traditioneller Architektur und bietet ein einzigartiges Erlebnis am Persischen Golf. Das Design integriert eine malerische Marina, einen traditionellen Souq und eine moderne Mall, die durch Brücken und Promenaden miteinander verbunden sind. Ein markantes Merkmal ist die große musikalische Fontäne, die regelmäßig Wasserspiele zeigt und besonders abends Besucher anzieht. Al Kout Mall bietet eine breite Palette an internationalen Marken, Kinos und vielfältigen gastronomischen Einrichtungen mit Blick auf das Meer. Die Verbindung zum Meer ist durch den Fischmarkt und den Hafen für Fischerboote allgegenwärtig, was dem Ort eine authentische Atmosphäre verleiht. Mit seiner Erweiterung in den letzten Jahren hat Al Kout seine Position als führendes Einkaufs- und Freizeitzentrum im Süden Kuwaits gefestigt. Es dient nicht nur als Handelsplatz, sondern auch als sozialer Treffpunkt, der kulturelles Erbe mit zeitgenössischem Komfort verbindet.",
      hu: "Az Al Kout Mall Fahaheel negyedében található, és az Al Kout projekt központi elemeként Kuvait legnagyobb tengerparti szabadidős komplexuma. Az épületegyüttes a modern kereskedelmet ötvözi a hagyományos arab építészettel, egyedülálló élményt nyújtva a Perzsa-öböl partján. A fejlesztés része egy festői jachtkikötő, egy tradicionális piac (souq) és egy modern bevásárlóközpont, amelyeket sétányok és hidak kötnek össze. Az egyik legnépszerűbb látványosság a hatalmas zenélő szökőkút, amely rendszeres vízijátékokkal szórakoztatja a közönséget, különösen az esti órákban. Az Al Kout Mall nemzetközi márkák széles választékát, mozit és számos tengerre néző éttermet kínál. A tengeri kapcsolatot erősíti a helyi halpiac és a halászhajók kikötője, amely autentikus hangulatot kölcsönöz a területnek. A közelmúltbeli bővítések révén az Al Kout megszilárdította helyét Kuvait déli részének vezető bevásárló- és szórakoztatóközpontjaként, ahol a kulturális örökség és a modern kényelem találkozik.",
      ro: "Al Kout Mall, situat în zona Fahaheel, este piesa centrală a proiectului Al Kout, cea mai mare destinație de lifestyle pe malul apei din Kuweit. Complexul îmbină armonios retailul modern cu arhitectura tradițională, oferind o experiență unică pe malul Golfului Persic. Designul integrează o marină pitorească, un souq (piață tradițională) și un mall contemporan, toate conectate prin promenade și poduri. O trăsătură distinctivă este fântâna muzicală impresionantă, care oferă spectacole periodice de apă și lumină, atrăgând mulțimi de vizitatori în special seara. Al Kout Mall găzduiește o gamă variată de branduri internaționale, cinematografe și numeroase opțiuni de luat masa cu vedere spre mare. Conexiunea cu tradiția maritimă este menținută prin piața de pește activă și portul pentru ambarcațiuni de pescuit, oferind locului o atmosferă autentică. Extinderile recente au consolidat poziția Al Kout ca principal centru comercial și de divertisment din sudul Kuweitului, fiind un punct de întâlnire social unde moștenirea culturală se întâlnește cu confortul modern.",
      en: "Al Kout Mall in Fahaheel is the centerpiece of the Al Kout Project, Kuwait's largest waterfront retail and leisure destination. The complex masterfully blends modern commercial design with traditional Kuwaiti architecture, creating a unique atmosphere along the Persian Gulf. The development integrates several distinct areas, including a luxury mall, a traditional-style souq, a scenic marina, and a pier. One of its most famous attractions is the large musical fountain, which performs synchronized water displays that are especially captivating after sunset. Al Kout Mall offers an extensive selection of global retail brands, high-end cinemas, and a variety of dining venues with terrace views overlooking the water. The site maintains a connection to its maritime roots through an active fish market and a harbor for local dhows and fishing boats. Following its major expansion, Al Kout has become the premier social and shopping hub in southern Kuwait, effectively merging cultural heritage with contemporary lifestyle amenities.",
      es: "Al Kout Mall es un gran centro comercial en Al Fahaheel, Kuwait, directamente en el Golfo Pérsico. Inaugurado en 2009, ofrece una superficie de venta de 90.000 metros cuadrados con más de 150 tiendas. El centro comercial también incluye una réplica de un zoco tradicional, un parque de atracciones para niños y un área de restauración. La arquitectura combina el diseño moderno con elementos tradicionales kuwaitíes. Cuenta con una marina con 50 amarres para barcos. Al Kout Mall es un destino popular para familias y turistas.",
      pt: "O Al Kout Mall é um grande centro comercial em Al Fahaheel, Kuwait, diretamente no Golfo Pérsico. Foi inaugurado em 2009 e oferece uma área de vendas de 90.000 metros quadrados com mais de 150 lojas. O centro comercial também inclui uma réplica de um souk tradicional, um parque de diversões para crianças e uma zona de restauração. A arquitetura combina o design moderno com elementos tradicionais do Kuwait. Existe uma marina com 50 lugares de amarração para barcos. O Al Kout Mall é um destino popular para famílias e turistas.",
      fr: "Al Kout Mall est un grand centre commercial situé à Al Fahaheel, au Koweït, directement au bord du golfe Persique. Ouvert en 2009, il offre une surface de vente de 90 000 mètres carrés avec plus de 150 boutiques. Le centre commercial comprend également une réplique d'un souk traditionnel, un parc d'attractions pour enfants et une aire de restauration. L'architecture allie un design moderne à des éléments koweïtiens traditionnels. Il dispose d'une marina de 50 anneaux pour les bateaux. Al Kout Mall est une destination prisée des familles et des touristes.",
    },
