      de: ["Al Kout Mall ist Teil eines 300.000 Quadratmeter großen Gesamtprojekts.", "Die musikalische Fontäne ist eine der größten ihrer Art in Kuwait.", "Der Komplex umfasst sechs verschiedene Zonen, darunter den Al Kout Souq.", "Es gibt direkte Liegeplätze für über 150 Yachten in der angeschlossenen Marina.", "Die Mall wurde zuletzt im Jahr 2018 umfassend erweitert und modernisiert.", "Fahaheel, wo sich die Mall befindet, ist ein historisches Zentrum des Seehandels."],
