      es: ["Inauguración en 2009.", "Superficie de venta 90.000 metros cuadrados.", "Más de 150 tiendas.", "50 amarres en la marina.", "Área de restauración con 30 restaurantes.", "Parque de atracciones en 5.000 metros cuadrados."],
